import{_ as e,o as r,c as o,a2 as t}from"./chunks/framework.F7eQ-ohH.js";const i="/bzygq/assets/ecc0eee5773f4faf91dba339d3907572.BF55xb7t.png",f=JSON.parse('{"title":"02 Topic、Partition、Broker与副本机制","description":"","frontmatter":{},"headers":[],"relativePath":"Java面试问题汇总/Kafka/02 Topic、Partition、Broker与副本机制.md","filePath":"Java面试问题汇总/Kafka/02 Topic、Partition、Broker与副本机制.md","lastUpdated":1788929995000}'),p={name:"Java面试问题汇总/Kafka/02 Topic、Partition、Broker与副本机制.md"};function d(c,a,n,l,s,k){return r(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="_02-topic、partition、broker与副本机制" tabindex="-1">02 Topic、Partition、Broker与副本机制 <a class="header-anchor" href="#_02-topic、partition、broker与副本机制" aria-label="Permalink to &quot;02 Topic、Partition、Broker与副本机制&quot;">​</a></h1><p>理解 Kafka 集群时，可以先抓住一句话：Topic 是业务入口，Partition 是实际日志，Broker 是日志副本所在的节点，Replica 是分区的高可用副本。Kafka 的扩展性来自 Partition，容错能力来自 Replica，读写入口来自 Leader，数据安全边界由 ISR 和 HW 共同约束。</p><p>很多 Kafka 问题看起来分散，实际都围绕这一组对象展开。为什么一个 Topic 能被多个消费者并行处理，是因为 Topic 被拆成多个 Partition；为什么只能保证局部有序，是因为顺序只存在于单个 Partition 的日志内；为什么 Broker 宕机后不一定丢数据，是因为每个 Partition 可以配置多个 Replica；为什么 acks=all 还要配 min.insync.replicas，是因为“写入成功”的承诺必须和同步副本数量绑定。</p><h2 id="topic规划不是只取一个业务名" tabindex="-1">Topic规划不是只取一个业务名 <a class="header-anchor" href="#topic规划不是只取一个业务名" aria-label="Permalink to &quot;Topic规划不是只取一个业务名&quot;">​</a></h2><p>Topic 是 Kafka 面向业务的消息流名称，但 Topic 规划并不只是起名。创建 Topic 时通常至少要确定三个维度：业务语义、分区数和副本因子。业务语义决定哪些消息可以放在同一条流里；分区数决定写入、存储和消费的并行度；副本因子决定可容忍的 Broker 故障范围。</p><p>Topic 粒度过粗，会让不同业务混在一起，消费者需要额外过滤，保留策略和权限也难以独立配置。Topic 粒度过细，又会带来大量小 Topic、小分区，增加 Controller 元数据压力、文件句柄数量和运维复杂度。实际项目中常见做法是按稳定的业务事件建 Topic，例如订单创建、支付成功、设备指标、用户行为日志，而不是按每个调用方随意建 Topic。</p><p>分区数也不是越多越好。更多分区意味着更高的潜在并行度，但也意味着更多日志文件、索引文件、Leader/Follower 状态、网络复制流和 Rebalance 成本。估算分区数时通常要同时看生产端吞吐、单分区可承载写入量、消费者组最大并行度、消息大小、峰值流量和未来扩容空间。对于强顺序业务，还要提前考虑分区扩容会不会破坏 Key 到分区的稳定映射。</p><h2 id="partition是日志、并行度和顺序性的交汇点" tabindex="-1">Partition是日志、并行度和顺序性的交汇点 <a class="header-anchor" href="#partition是日志、并行度和顺序性的交汇点" aria-label="Permalink to &quot;Partition是日志、并行度和顺序性的交汇点&quot;">​</a></h2><p>Partition 在物理上是一条只追加的日志。Producer 写入某个 Partition 后，消息会被追加到日志尾部，并获得递增的 Offset。Consumer 拉取时也是按 Offset 顺序读取，所以单个 Partition 内天然有顺序。但一个 Topic 如果有多个 Partition，Kafka 不维护跨分区全局顺序，因为全局排序会把多个分区重新收束成一个串行瓶颈，抵消 Kafka 的吞吐优势。</p><p>顺序性设计必须落到业务 Key。假设同一个订单会产生“创建、支付、发货、完成”四类事件，如果这些事件被路由到不同 Partition，消费者就可能并行读到后续事件，导致状态机处理错乱。更稳妥的做法是使用订单 ID 作为消息 Key，让分区器把同一个订单的事件路由到同一 Partition。这样 Kafka 保证的是同一订单维度的顺序，而不是整个订单 Topic 的全局顺序。</p><p>Partition 也是消费并行度的上限。同一个消费者组内，一个 Partition 同一时刻只能交给一个消费者实例处理。如果 Topic 只有 3 个分区，即使启动 10 个消费者实例，也只有 3 个实例会真正消费，其余实例处于空闲或备用状态。因此“增加消费者实例”只有在分区数足够时才有效；如果瓶颈集中在某个热点分区，还要进一步分析 Key 分布和单条消息处理耗时。</p><h2 id="broker承载副本而不是充当全局主节点" tabindex="-1">Broker承载副本而不是充当全局主节点 <a class="header-anchor" href="#broker承载副本而不是充当全局主节点" aria-label="Permalink to &quot;Broker承载副本而不是充当全局主节点&quot;">​</a></h2><p>Broker 是 Kafka 集群中的服务进程或节点，负责处理客户端请求、存储日志、维护副本状态并参与集群管理。一个 Broker 可以同时保存多个 Topic 的多个 Partition 副本，也可能同时承担一些分区的 Leader 和另一些分区的 Follower。Kafka 没有“所有写入都先进入某台主 Broker”的模型，Leader 角色是按 Partition 分散的。</p><p>这种设计让集群能够横向扩展。比如一个 Topic 有 12 个 Partition，分布在 3 台 Broker 上，Kafka 可以把不同 Partition 的 Leader 均匀放到不同 Broker，使生产者写入和消费者读取分散到多台机器。如果某台 Broker 既承载大量 Leader，又承载高流量 Topic，就可能出现负载倾斜，需要通过分区重分配或 Leader 均衡来调整。</p><p>Broker 层还承担客户端元数据查询。Producer 和 Consumer 会通过 bootstrap.servers 连接集群中的任意可用 Broker，拉取 Topic、Partition、Leader 所在节点等元数据，然后再把请求发往对应 Leader。配置多个 bootstrap 地址的意义不是每条消息都发给这些节点，而是提高客户端发现集群的成功率。</p><h2 id="replica让分区具备故障恢复能力" tabindex="-1">Replica让分区具备故障恢复能力 <a class="header-anchor" href="#replica让分区具备故障恢复能力" aria-label="Permalink to &quot;Replica让分区具备故障恢复能力&quot;">​</a></h2><p>Replica 是 Partition 的副本。一个 Partition 如果副本因子为 3，就会有 3 份副本分散在不同 Broker 上，其中一个是 Leader，其余是 Follower。Producer 写入和 Consumer 读取默认都面向 Leader；Follower 不直接服务普通读写请求，而是持续从 Leader 拉取数据，尽量保持和 Leader 一致。</p><p>Leader/Follower 是副本角色，不是 Broker 角色。同一台 Broker 上可能有 A 分区的 Leader、B 分区的 Follower、C 分区的 Leader。这样做的好处是读写压力可以按分区摊开；当某个 Broker 故障时，只影响它上面承载的那些副本，其他 Broker 可以为受影响分区重新选出 Leader。</p><p>副本因子决定容错空间。副本因子为 1 时，Broker 一旦丢失该分区日志，数据就没有其他副本可恢复；副本因子为 3 时，只要至少有满足条件的同步副本存活，Kafka 就可以继续提供服务。生产环境里，重要业务 Topic 通常会采用副本因子 3，再配合可靠写入参数，而不是只依赖单副本提升吞吐。</p><h2 id="isr与hw定义了安全可读的位置" tabindex="-1">ISR与HW定义了安全可读的位置 <a class="header-anchor" href="#isr与hw定义了安全可读的位置" aria-label="Permalink to &quot;ISR与HW定义了安全可读的位置&quot;">​</a></h2><p>Kafka 不要求所有 Follower 在每个时刻都和 Leader 完全一致，因为分布式系统里网络抖动、磁盘抖动、GC 暂停都会造成短暂落后。Kafka 使用 ISR（In-Sync Replicas，同步副本集合）描述当前跟得上 Leader 的副本。Leader 一定属于 ISR；Follower 只有复制进度满足要求，才会留在 ISR 中；如果长时间落后，就会被移出 ISR。</p><p>HW（High Watermark，高水位）可以理解为消费者安全可见的位置。Leader 日志末尾位置称为 LEO（Log End Offset），Follower 各自也有自己的 LEO。只有当消息被 ISR 中必要副本同步到之后，分区的 HW 才会向前推进。消费者正常只能读取 HW 以下的数据，这样可以避免读到 Leader 上尚未充分同步、Leader 故障后可能消失的消息。</p><table tabindex="0"><thead><tr><th>概念</th><th>含义</th><th>用来判断什么</th></tr></thead><tbody><tr><td>Leader</td><td>当前分区对外处理读写的副本</td><td>客户端请求应该发往哪里</td></tr><tr><td>Follower</td><td>从 Leader 拉取数据的副本</td><td>故障时是否有候选副本</td></tr><tr><td>ISR</td><td>与 Leader 保持同步的副本集合</td><td>写入确认和选主安全边界</td></tr><tr><td>LEO</td><td>某个副本日志末尾的下一位 Offset</td><td>副本已经复制到哪里</td></tr><tr><td>HW</td><td>消费者可安全读取的最高位置</td><td>哪些消息已经提交可见</td></tr></tbody></table><p>下面这张图把写入、Follower 同步、ISR 约束和 HW 推进放在同一条链路里。它是理解 Kafka 可靠性的核心图：Producer 不是把消息发给所有副本，而是写 Leader；Follower 从 Leader 复制；Leader 根据副本同步状态推进可见位置并返回确认。</p><p><img src="'+i+'" alt="images/kafka-02-写入复制链路.png"></p><p>images/kafka-02-写入复制链路.png</p><h2 id="写入确认要把acks和min-insync-replicas一起看" tabindex="-1">写入确认要把acks和min.insync.replicas一起看 <a class="header-anchor" href="#写入确认要把acks和min-insync-replicas一起看" aria-label="Permalink to &quot;写入确认要把acks和min.insync.replicas一起看&quot;">​</a></h2><p>Producer 的 acks 决定服务端什么情况下给生产者返回成功。acks=0 表示生产者不等待 Broker 确认，吞吐高但可靠性最低；acks=1 表示 Leader 写入成功即可返回，如果 Leader 返回后还没复制给 Follower 就故障，已确认消息可能丢失；acks=all 或 acks=-1 表示 Leader 需要等待 ISR 中副本满足条件后再返回成功。</p><p>只配置 acks=all 仍然不够，还要看服务端的 min.insync.replicas。例如副本因子为 3，min.insync.replicas=2，意味着至少需要 Leader 加一个同步副本处于 ISR 中，写入才可以被接受并确认。如果 ISR 缩小到只剩 Leader，Kafka 会拒绝写入，从而避免在“只有一份同步数据”的情况下继续承诺可靠写入。</p><p>生产环境里较常见的可靠组合是：Topic 副本因子 3，Producer 使用 acks=all，Topic 或 Broker 配置 min.insync.replicas=2，并关闭不干净 Leader 选举。这个组合不是绝对模板，但它体现了可靠性思路：允许一台 Broker 故障后继续服务；当同步副本不足时宁愿让写入失败，也不轻易确认可能丢失的数据。</p><h2 id="leader故障后的选举取舍" tabindex="-1">Leader故障后的选举取舍 <a class="header-anchor" href="#leader故障后的选举取舍" aria-label="Permalink to &quot;Leader故障后的选举取舍&quot;">​</a></h2><p>当某个 Partition 的 Leader 所在 Broker 故障时，Kafka 需要为该 Partition 选出新的 Leader。最安全的候选范围是 ISR，因为 ISR 中的副本跟上了 Leader 的已提交进度，能最大程度保留已经确认给生产者的消息。如果从 ISR 外的落后副本选 Leader，就可能出现服务恢复了，但部分已确认消息消失的情况。</p><p>unclean.leader.election.enable 控制是否允许不干净 Leader 选举。关闭它时，Kafka 不会从非 ISR 副本中选 Leader，数据安全性更好，但如果所有 ISR 副本都不可用，分区可能暂时不可写甚至不可读。开启它时，可用性更强，落后副本也可能被选为 Leader，但代价是可能丢失已确认消息。</p><p>面试表达时要明确这是可用性和一致性的取舍。订单、支付、资金、设备告警这类关键数据通常更倾向于关闭不干净选举，接受短暂不可用；访问日志、可重采集指标、可补偿埋点等场景可以根据业务容忍度进行不同配置。不要把某个参数值背成所有场景的标准答案。</p><h2 id="分区扩容会改变并行度-也可能改变语义" tabindex="-1">分区扩容会改变并行度，也可能改变语义 <a class="header-anchor" href="#分区扩容会改变并行度-也可能改变语义" aria-label="Permalink to &quot;分区扩容会改变并行度，也可能改变语义&quot;">​</a></h2><p>Kafka 允许增加 Topic 的分区数，但不能直接减少分区数。增加分区后，Topic 的潜在写入和消费并行度会提高，新分区也可以承接后续消息。但扩容不是完全无成本，尤其当业务依赖 Key 顺序时，需要非常谨慎。</p><p>默认 Key 分区策略通常会对 Key 的哈希值按分区数取模。假设原来有 6 个分区，某个订单 ID 被路由到分区 2；扩容到 12 个分区后，同一个订单 ID 的哈希取模结果可能变成另一个分区。这样扩容前后的同一业务 Key 消息就会落到不同 Partition，消费者可能在两个分区中并行处理同一订单的历史事件和新事件，破坏顺序性。</p><p>工程上有几种规避思路。第一，在 Topic 创建初期为强顺序、高增长业务预留足够分区，避免频繁扩容。第二，使用自定义分区策略或固定映射，让关键业务 Key 在扩容前后仍尽量保持原分区。第三，把强顺序对象按业务域拆分 Topic，降低单个 Topic 扩容影响面。第四，在扩容切换窗口中暂停相关生产消费，等待旧分区消息处理完成后再放开新路由。具体采用哪种方式，要根据业务对顺序、可用性和运维复杂度的要求选择。</p><h2 id="副本机制的常见项目表达" tabindex="-1">副本机制的常见项目表达 <a class="header-anchor" href="#副本机制的常见项目表达" aria-label="Permalink to &quot;副本机制的常见项目表达&quot;">​</a></h2><p>项目里描述 Kafka 可靠性时，可以按“副本布局、写入确认、选主策略、消费幂等”四层来说。副本布局回答数据有没有多份；写入确认回答什么情况下告诉生产者成功；选主策略回答故障后是否允许落后副本接管；消费幂等回答即使消息重复到达，下游是否能保证业务结果正确。</p><p>一个较完整的表述可以是：核心业务 Topic 设置 3 副本，生产者使用 acks=all，Topic 配置 min.insync.replicas=2，同时关闭不干净 Leader 选举，避免从落后副本中恢复服务造成已确认消息丢失。消费侧按业务主键做幂等写入，Offset 在业务处理成功后提交，配合积压监控和失败重试，保证故障恢复时最多重复处理，不轻易丢数据。</p><p>需要注意，Kafka 的副本机制解决的是 Broker 节点故障下的数据可用性和一致性问题，不自动解决所有业务可靠性问题。比如消费者处理到一半失败、下游数据库写入成功但 Offset 未提交、生产者重试导致重复消息，这些都需要在生产者幂等、事务、消费者提交策略和业务幂等中继续处理。</p><h2 id="本章需要掌握的判断线" tabindex="-1">本章需要掌握的判断线 <a class="header-anchor" href="#本章需要掌握的判断线" aria-label="Permalink to &quot;本章需要掌握的判断线&quot;">​</a></h2><p>Topic 是业务消息流，Partition 是实际日志和并行边界，Broker 是承载分区副本的节点，Replica 是容错基础，Leader 负责对外读写，Follower 负责从 Leader 同步，ISR 表示当前同步健康的副本集合，HW 表示消费者安全可见的位置。</p><p>围绕这条判断线，Kafka 的几个高频问题就能串起来：单分区有序、多分区无全局顺序；消费者组并行度不能超过分区数；可靠写入要同时看副本因子、acks、min.insync.replicas 和选主策略；分区扩容能提升并行度，但可能改变 Key 到 Partition 的映射。能把这些边界说清楚，后面学习 Producer、Broker 存储和 Consumer Rebalance 时会顺很多。</p>',45)])])}const P=e(p,[["render",d]]);export{f as __pageData,P as default};
